update public.outings set public_notes = 'El calendario provincial general también ha denominado este acto traslado extraordinario al cementerio. Soporte procesional: pendiente de documentación específica; no se crea paso ni andas sin fuente suficiente. Música: sin formación confirmada en las fuentes revisadas a fecha 7 de septiembre de 2026.' where id = 'edd4502e-d5b0-4c6d-b28c-ba0155501d04';
update public.outings set public_notes = 'El calendario provincial más reciente denomina el acto “Procesión extraordinaria de los titulares del Santo Entierro”. La Banda de Cornetas y Tambores Nuestro Padre Jesús Nazareno de Arahal acompañará el primer tramo del recorrido. El acompañamiento musical del resto de la procesión permanece por confirmar. Soporte procesional: pendiente de documentación específica; no se crea paso ni andas sin fuente suficiente. Recorrido: pendiente de documentación específica; no se ha incorporado un itinerario no confirmado.' where id = '4d580db8-9406-4fee-9bb3-a0af569c76e7';
update public.outings set public_notes = 'El programa conmemorativo del XXX aniversario de la Coronación Canónica contempla cultos y actos extraordinarios durante octubre de 2026. El Rosario comenzó a las 10:00 y llegó a la Parroquia en torno a las 12:00. Soporte procesional: pendiente de documentación específica; no se crea paso ni andas sin fuente suficiente.' where id = '8818aa00-e7a0-410f-badc-41336d8655ab';
update public.outings set public_notes = 'La imagen permanecerá durante la noche en el Barrio de la Estación. Está documentado acompañamiento musical, pero no la formación. La salida procesional extraordinaria propiamente dicha del aniversario está prevista para 2027. Soporte procesional: pendiente de documentación específica; no se crea paso ni andas sin fuente suficiente.' where id = 'e79c523b-cb0a-4a2e-9903-bbd7abfe0df2';
